using System;using System.IO;using System.Linq;using System.Runtime.CompilerServices;using GdUnit4;using Godot;namespace NewGameProject.Tests.XUnit;public partial class Steps{    public void AssertScreenshot(string relativeImagePath, float tolerance = 0.01f,        [CallerFilePath] string callerPath = "")    {        var actualName = DateTime.Now.ToFileTimeUtc() + "_actual.png";        var actualPath = DebugSaveScreenshot(actualName, callerPath);        string baseDir = Path.GetDirectoryName(callerPath);        string fullExpectedPath = Path.Combine(baseDir, relativeImagePath);        string godotPath = ProjectSettings.LocalizePath(fullExpectedPath);        // Ensure expected exists        if (!File.Exists(fullExpectedPath))        {            Assertions.AssertBool(false).OverrideFailureMessage($"Reference not found at: {fullExpectedPath}").IsTrue();            return;        }        // Compare bytes for exact match. If you need visual tolerance, implement pixel-wise comparison here.        bool equal = false;        try        {            var actualBytes = File.ReadAllBytes(actualPath);            var expectedBytes = File.ReadAllBytes(fullExpectedPath);            if (actualBytes.Length == expectedBytes.Length)            {                equal = actualBytes.SequenceEqual(expectedBytes);            }        }        catch (Exception ex)        {            Assertions.AssertBool(false).OverrideFailureMessage($"Error comparing images: {ex.Message}").IsTrue();            return;        }        Assertions.AssertBool(equal)            .OverrideFailureMessage($"Image mismatch! Actual: \"{actualPath}\" vs Expected: \"{relativeImagePath}\"")            .IsTrue();        File.Delete(actualPath);    }}